<script setup lang="ts">import type{ApiSuccess,PublicContent}from'~/types/api';useHead({title:'Actualités'});const{data}=await useFetch<ApiSuccess<PublicContent[]>>('/api/public/content');const items=computed(()=>(data.value?.data??[]).filter(item=>['NEWS','ARTICLE','RND'].includes(item.kind)))</script>
<template><section class="section"><div class="container"><p class="eyebrow">Actualités & publications</p><h1 class="display-title">Suivre les projets, les idées et les ressources IFICS.</h1><div v-if="items.length" class="grid grid-3 list"><article v-for="item in items" :key="item.id" class="card card-pad"><span class="badge">{{item.kind}}</span><h2>{{item.title}}</h2><p>{{item.excerpt}}</p><NuxtLink :to="`/actualites/${item.slug}`">Lire →</NuxtLink></article></div><div v-else class="empty-state">Aucune publication n’est actuellement disponible.</div></div></section></template>
